//! Independent public-boundary matrix for the natural-key record codecs.
//!
//! Every expected image comes from `tests/fixtures/natural-structural/`, generated by a
//! separate Python encoder from the spec tables (`PROVENANCE.md`). Nothing here takes an
//! expected byte from the encoder it checks, so a symmetric width or ordering mistake
//! cannot agree with itself.
//!
//! Coverage per family: exact golden encode, exact golden decode, mandatory-field
//! removal, foreign-field refusal, declared width/limit bounds, and the two resource
//! boundaries (budget refusal before publication, cancellation on an empty read).

use sage_db_format::{
    event::{self, EVENT_FLAG_REQUIRED},
    natural::*,
    wire::{DecodeError, ReadError, Reader, WriteError, Writer},
};
use sage_db_types::{
    identity::RecordRevision,
    ledger::{BudgetError, BudgetUnit, SharedLedger},
    persist::*,
    query::ControlStop,
};

const FIXTURES: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/natural-structural"
);

// ---------------------------------------------------------------------------
// Ledgers
// ---------------------------------------------------------------------------

/// Records every charge, so a test can assert what was admitted and in what unit.
#[derive(Default)]
struct Open {
    bytes: Vec<u64>,
    entries: Vec<u64>,
}

impl SharedLedger for Open {
    fn try_charge(&mut self, bytes: u64) -> Result<(), BudgetError> {
        self.bytes.push(bytes);
        Ok(())
    }
    fn try_charge_entries(&mut self, count: u64) -> Result<(), BudgetError> {
        self.entries.push(count);
        Ok(())
    }
    fn checkpoint(&mut self) -> Result<(), ControlStop> {
        Ok(())
    }
}

/// Allows at most `bytes` total, then refuses. Entry allowance is unlimited so a byte
/// refusal is never confused with an entry refusal.
struct ByteBudget(u64);

impl SharedLedger for ByteBudget {
    fn try_charge(&mut self, bytes: u64) -> Result<(), BudgetError> {
        if bytes > self.0 {
            return Err(BudgetError::new(BudgetUnit::Bytes, bytes, self.0));
        }
        self.0 -= bytes;
        Ok(())
    }
    fn try_charge_entries(&mut self, _count: u64) -> Result<(), BudgetError> {
        Ok(())
    }
    fn checkpoint(&mut self) -> Result<(), ControlStop> {
        Ok(())
    }
}

/// Cancels every checkpoint, which must be observed even on an empty collection.
struct Cancelled;

impl SharedLedger for Cancelled {
    fn try_charge(&mut self, _bytes: u64) -> Result<(), BudgetError> {
        Ok(())
    }
    fn try_charge_entries(&mut self, _count: u64) -> Result<(), BudgetError> {
        Ok(())
    }
    fn checkpoint(&mut self) -> Result<(), ControlStop> {
        Err(ControlStop::Cancelled)
    }
}

// ---------------------------------------------------------------------------
// Fixture loading
// ---------------------------------------------------------------------------

/// A mandatory fixture, or a hard panic: a missing input must never look like a pass.
fn fixture(name: &str) -> Vec<u8> {
    let path = format!("{FIXTURES}/{name}.hex");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("mandatory fixture {path} is unreadable: {error}"));
    let hex: String = text.trim().to_owned();
    assert!(!hex.is_empty(), "fixture {path} is empty");
    assert_eq!(hex.len() % 2, 0, "fixture {path} has an odd hex length");
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex"))
        .collect()
}

fn encode(f: impl FnOnce(&mut Writer<'_>) -> Result<(), WriteError>) -> Vec<u8> {
    let mut out = Vec::new();
    let mut ledger = Open::default();
    f(&mut Writer::new(&mut out, &mut ledger)).expect("encode");
    out
}

/// Rewrite one decoded event's fields, so a mutation test changes exactly one thing.
fn edit(
    bytes: &[u8],
    tag: Option<u16>,
    drop: Option<u16>,
    replace: Option<(u16, Vec<u8>)>,
) -> Vec<u8> {
    let mut ledger = Open::default();
    let event = event::read_event(&mut Reader::new(bytes), &mut ledger).expect("framing");
    let mut fields: Vec<(u16, Vec<u8>)> = event
        .fields()
        .iter()
        .filter(|field| Some(field.tag()) != drop)
        .filter(|field| replace.as_ref().is_none_or(|(t, _)| *t != field.tag()))
        .map(|field| (field.tag(), field.value().to_vec()))
        .collect();
    if let Some(pair) = replace {
        fields.push(pair);
    }
    fields.sort_by_key(|(tag, _)| *tag);
    let mut out = Vec::new();
    out.extend_from_slice(&tag.unwrap_or(event.tag()).to_le_bytes());
    out.extend_from_slice(&EVENT_FLAG_REQUIRED.to_le_bytes());
    out.extend_from_slice(&(fields.len() as u16).to_le_bytes());
    for (tag, value) in fields {
        out.extend_from_slice(&tag.to_le_bytes());
        out.extend_from_slice(&0u16.to_le_bytes());
        out.extend_from_slice(&(value.len() as u32).to_le_bytes());
        out.extend_from_slice(&value);
    }
    out
}

fn text(value: &str) -> Vec<u8> {
    let mut out = (value.len() as u32).to_le_bytes().to_vec();
    out.extend_from_slice(value.as_bytes());
    out
}

fn creation(origin: ActorOrigin, recorded_by: Option<&str>, created_at: i64) -> CreationAudit {
    CreationAudit {
        recorded_by: recorded_by.map(str::to_owned),
        actor_origin: origin,
        reason: None,
        created_at,
    }
}

