/// Row 192 makes tag 5 unconditional, event-specifically (coordinator ruling (iii),
/// 2026-11-17). The full matrix the ruling named, asserted on **both** the write and the
/// read path so neither side can drift from the other:
///
/// | origin | tag 5 | verdict |
/// |---|---|---|
/// | 0 authenticated | present | accepted (positive) |
/// | 1 legacy_declared | present | accepted (positive) |
/// | 0 | absent | refused |
/// | 1 | absent | refused |
/// | 2 unavailable | absent | refused |
/// | 2 | present | refused |
///
/// The two negatives a global rule alone would not separate are rows 3 and 4:
/// `origin = 1` without tag 5 looks legal under the section 6.1 class conditional but
/// violates row 192. Rows 5 and 6 are the origin-2 arms: without tag 5 the row's own list
/// is violated, with tag 5 the joint table is. Their error kinds differ on purpose so a
/// reader can tell them apart.
#[test]
fn outcome_tag_five_is_unconditional_matrix() {
    let base = outcome_min();

    // --- positives -----------------------------------------------------------
    for origin in [ActorOrigin::Authenticated, ActorOrigin::LegacyDeclared] {
        let mut record = base.clone();
        record.audit.actor_origin = origin;
        record.audit.recorded_by = Some("actor".into());
        let bytes = encode(|w| write_request_outcome(w, &record));
        let decoded =
            read_request_outcome(&mut Reader::new(&bytes), &mut Open::default()).expect("decode");
        assert_eq!(decoded, record, "{origin:?} with tag 5 must round-trip");
    }

    // --- negatives on the write path: nothing is published -------------------
    let negatives = [
        (ActorOrigin::Authenticated, false, "missing"),
        (ActorOrigin::LegacyDeclared, false, "missing"),
        (ActorOrigin::Unavailable, false, "missing"),
        (ActorOrigin::Unavailable, true, "mismatch"),
    ];
    for (origin, five, expected) in negatives {
        let mut record = base.clone();
        record.audit.actor_origin = origin;
        record.audit.recorded_by = if five { Some("actor".into()) } else { None };
        let mut out = Vec::new();
        let mut ledger = Open::default();
        let error = write_request_outcome(&mut Writer::new(&mut out, &mut ledger), &record)
            .expect_err("illegal origin/tag-5 combination must be refused");
        assert!(
            out.is_empty(),
            "{origin:?} five={five}: a refused encode must publish nothing"
        );
        match expected {
            "missing" => assert!(
                matches!(
                    error,
                    WriteError::Data(sage_db_format::wire::EncodeError::MissingRequiredField {
                        event: 192,
                        field: 5
                    })
                ),
                "{origin:?} five={five}: {error:?}"
            ),
            _ => assert!(
                matches!(
                    error,
                    WriteError::Data(sage_db_format::wire::EncodeError::ActorOriginMismatch {
                        tag: 5
                    })
                ),
                "{origin:?} five={five}: {error:?}"
            ),
        }
    }

    // --- negatives on the read path, each from one edited fact ---------------
    let legal = encode(|w| write_request_outcome(w, &base));
    // Drop tag 5 and keep every other field, so exactly one thing changed.
    let without_five = edit(&legal, None, Some(5), None);
    for origin in [
        ActorOrigin::Authenticated,
        ActorOrigin::LegacyDeclared,
        ActorOrigin::Unavailable,
    ] {
        let raw = edit(
            &without_five,
            None,
            None,
            Some((6, (origin as u16).to_le_bytes().to_vec())),
        );
        assert!(
            matches!(
                read_request_outcome(&mut Reader::new(&raw), &mut Open::default()),
                Err(ReadError::Data(DecodeError::MissingField {
                    event: 192,
                    field: 5
                }))
            ),
            "{origin:?} without tag 5 must be MissingField{{192,5}} on read"
        );
    }
    // Origin 2 *with* tag 5: the row's list is satisfied, the joint table is not.
    let origin_two_with_five = edit(
        &legal,
        None,
        None,
        Some((6, (ActorOrigin::Unavailable as u16).to_le_bytes().to_vec())),
    );
    assert!(
        matches!(
            read_request_outcome(
                &mut Reader::new(&origin_two_with_five),
                &mut Open::default()
            ),
            Err(ReadError::Data(DecodeError::ActorOriginMismatch { tag: 5 }))
        ),
        "origin 2 with tag 5 must be ActorOriginMismatch{{5}}"
    );
}

/// v1's origin-2 image is not merely decode-rejected: the corrected writer cannot
/// reproduce it at all. That separates the old rule from the new one on the write side.
#[test]
fn outcome_v1_origin_two_image_is_now_unencodable() {
    let mut record = outcome_min();
    record.audit.actor_origin = ActorOrigin::Unavailable;
    record.audit.recorded_by = None;
    let mut out = Vec::new();
    let mut ledger = Open::default();
    assert!(
        write_request_outcome(&mut Writer::new(&mut out, &mut ledger), &record).is_err(),
        "v1's origin-2 image cannot be produced by the corrected writer"
    );
    assert!(out.is_empty(), "a refused encode publishes nothing");
}

