#[test]
fn a_zero_byte_budget_refuses_the_encode_before_any_field_is_produced() {
    let mut out = Vec::new();
    let mut ledger = ByteBudget(0);
    let error = write_asset(&mut Writer::new(&mut out, &mut ledger), &asset_min())
        .expect_err("zero budget");
    assert!(matches!(error, WriteError::Budget(_)), "{error:?}");
    assert!(
        out.is_empty(),
        "nothing may be published after a budget refusal"
    );
}

#[test]
fn a_zero_byte_budget_refuses_the_decode() {
    let bytes = fixture("asset-full");
    let mut ledger = ByteBudget(0);
    let error = read_asset(&mut Reader::new(&bytes), &mut ledger).expect_err("zero budget");
    assert!(matches!(error, ReadError::Budget(_)), "{error:?}");
}

#[test]
fn cancellation_is_observed_on_an_empty_count_list() {
    // The minimum import fixture has `expected_counts` present with count 0, so the
    // cancellation is not hiding behind an element loop.
    let bytes = fixture("import-min");
    let error =
        read_import_bookkeeping(&mut Reader::new(&bytes), &mut Cancelled).expect_err("cancelled");
    assert!(
        matches!(error, ReadError::Stopped(ControlStop::Cancelled)),
        "{error:?}"
    );
}

#[test]
fn retained_count_table_is_charged_at_its_rust_slot_size() {
    let bytes = fixture("import-full");
    let mut ledger = Open::default();
    read_import_bookkeeping(&mut Reader::new(&bytes), &mut ledger).expect("decode");
    let wanted = (4 * core::mem::size_of::<CountPair>()) as u64;
    assert!(
        ledger.bytes.contains(&wanted),
        "retained slot bytes {wanted} not among charges {:?}",
        ledger.bytes
    );
    assert!(
        ledger.entries.contains(&4),
        "four admitted entries expected, saw {:?}",
        ledger.entries
    );
}

#[test]
fn an_empty_collection_is_never_encoded_as_a_zero_length_field() {
    // §8.1: absence is the whole field, and an empty list is a 4-byte zero count.
    let bytes = fixture("import-min");
    let mut ledger = Open::default();
    let event = event::read_event(&mut Reader::new(&bytes), &mut ledger).unwrap();
    let raw = event.field(186).expect("present empty list");
    assert_eq!(
        raw,
        &[0, 0, 0, 0],
        "empty list is a count, not an omitted field"
    );
}

#[test]
fn state_kinds_are_not_narrowed_to_identified_records() {
    // 10..=13 have no RecordKey; the count space must still reach them.
    for kind in [
        StateKind::Asset,
        StateKind::Model,
        StateKind::KbMetadata,
        StateKind::RuleConfig,
    ] {
        assert!(
            counted_record_kind(kind).is_none(),
            "{kind:?} must have no RecordKind"
        );
    }
    assert_eq!(counted_record_kind(StateKind::Term), Some(RecordKind::Term));
    assert!(is_immutable(StateKind::Asset));
    assert!(!is_immutable(StateKind::Model));
}

#[test]
fn state_kind_mapping_matches_storage_digests_4_4_8() {
    assert_eq!(state_kind(ASSET_DECLARED), Some(StateKind::Asset));
    assert_eq!(state_kind(KB_METADATA_UPDATED), Some(StateKind::KbMetadata));
    for tag in [MODEL_REGISTERED, MODEL_UPDATED, MODEL_RETIRED] {
        assert_eq!(state_kind(tag), Some(StateKind::Model));
    }
    assert_eq!(
        state_kind(RULE_PROFILE_CHANGED),
        Some(StateKind::RuleConfig)
    );
    // Not knowledge records: bookkeeping_digest only.
    assert_eq!(state_kind(REQUEST_OUTCOME_RECORDED), None);
    assert_eq!(state_kind(IMPORT_BOOKKEEPING), None);
}

